65	  private static final Logger LOG = JournalNode.LOG;
66	  private static final int HANDLER_COUNT = 5;
67	  private final JournalNode jn;
68	  private Server server;
69	
70	  JournalNodeRpcServer(Configuration conf, JournalNode jn) throws IOException {
71	    this.jn = jn;
72	    
73	    Configuration confCopy = new Configuration(conf);
74	    
75	    // Ensure that nagling doesn't kick in, which could cause latency issues.
76	    confCopy.setBoolean(
77	        CommonConfigurationKeysPublic.IPC_SERVER_TCPNODELAY_KEY,
78	        true);
79	    
80	    InetSocketAddress addr = getAddress(confCopy);
81	    String bindHost = conf.getTrimmed(DFS_JOURNALNODE_RPC_BIND_HOST_KEY, null);
82	    if (bindHost == null) {
83	      bindHost = addr.getHostName();
84	    }
85	    LOG.info("RPC server is binding to " + bindHost + ":" + addr.getPort());
86	
87	    RPC.setProtocolEngine(confCopy, QJournalProtocolPB.class,
88	        ProtobufRpcEngine2.class);
89	    QJournalProtocolServerSideTranslatorPB translator =
90	        new QJournalProtocolServerSideTranslatorPB(this);
91	    BlockingService service = QJournalProtocolService
92	        .newReflectiveBlockingService(translator);
93	    
94	    this.server = new RPC.Builder(confCopy)
95	        .setProtocol(QJournalProtocolPB.class)
96	        .setInstance(service)
97	        .setBindAddress(bindHost)
98	        .setPort(addr.getPort())
99	        .setNumHandlers(HANDLER_COUNT)
100	        .setVerbose(false)
101	        .build();
102	
103	
104	    //Adding InterQJournalProtocolPB to server
105	    InterQJournalProtocolServerSideTranslatorPB
106	        qJournalProtocolServerSideTranslatorPB = new
107	        InterQJournalProtocolServerSideTranslatorPB(this);
108	
109	    BlockingService interQJournalProtocolService = InterQJournalProtocolService
110	        .newReflectiveBlockingService(qJournalProtocolServerSideTranslatorPB);
111	
112	    DFSUtil.addPBProtocol(confCopy, InterQJournalProtocolPB.class,
113	        interQJournalProtocolService, server);
114	
115	
116	    // set service-level authorization security policy
117	    if (confCopy.getBoolean(
118	      CommonConfigurationKeys.HADOOP_SECURITY_AUTHORIZATION, false)) {
119	          server.refreshServiceAcl(confCopy, new HDFSPolicyProvider());
120	    }
121	    this.server.setTracer(jn.tracer);
122	  }
